def plus_age(eleves):
    meilleur = eleves[0]
    for e in eleves:
        if e[1] > meilleur[1]:
            meilleur = e
    return meilleur[0]

def bornes(L):
    mini = L[0]
    maxi = L[0]
    for x in L:
        if x < mini:
            mini = x
        if x > maxi:
            maxi = x
    return (mini, maxi)
